// delay — the repeats one hit leaves: each tap Feedback dB under the last, until they fall below -60 dB.
// The delay TIME is the plugin's own setting and no param, so the taps are evenly spaced.

const FB = "#3d7dff";
const DRY = "#ffffff";
const GRID = "#6b6b6b";
const FLOOR = -60;
const MAX_TAPS = 24;

export default {
  taps(lcd) {
    const { ctx, width: W, height: H, params, output, state, now } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);

    const fb = Math.min(0, Math.max(-30, params["Feedback"] ?? -6));
    // Repeats until -60 dB; at 0 dB it never dies, which the screen caps and says.
    const endless = fb > -0.05;
    const count = endless ? MAX_TAPS : Math.min(MAX_TAPS, Math.ceil(FLOOR / fb));

    const pad = 6;
    const top = 14;
    const base = H - pad;
    const span = Math.max(1, base - top);
    const step = (W - pad * 2 - 40) / (MAX_TAPS + 1);

    ctx.strokeStyle = GRID;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(pad, Math.round(base) + 0.5);
    ctx.lineTo(W - pad - 40, Math.round(base) + 0.5);
    ctx.stroke();

    // A tap's height is its level in dB mapped onto 0..-60, so a long tail reads as a slope.
    const heightOf = (db) => ((Math.max(FLOOR, db) - FLOOR) / -FLOOR) * span;
    // While audio leaves the module, a dot walks the repeats so the tail is seen moving.
    const out = Array.isArray(output) && output.length ? (output[output.length - 1] ?? 0) : 0;
    state.out = (state.out ?? 0) * 0.7 + out * 0.3;
    const lit = state.out > 0.02 ? Math.floor(now / 180) % (count + 1) : -1;

    for (let k = 0; k <= count; k++) {
      const x = Math.round(pad + step * k) + 0.5;
      const h = heightOf(fb * k);
      ctx.fillStyle = k === 0 ? DRY : FB;
      ctx.globalAlpha = k === lit ? 1 : k === 0 ? 0.9 : 0.75;
      ctx.fillRect(x - 1, base - h, 3, h);
    }
    ctx.globalAlpha = 1;

    // The one number that matters: how many repeats are heard.
    ctx.textAlign = "right";
    ctx.textBaseline = "top";
    ctx.fillStyle = FB;
    ctx.font = "8px ui-monospace, monospace";
    ctx.fillText("REPEATS", W - pad, 4);
    ctx.font = "16px ui-monospace, monospace";
    ctx.fillText(endless ? "INF" : String(count), W - pad, 16);
    ctx.font = "8px ui-monospace, monospace";
    ctx.fillStyle = GRID;
    ctx.fillText(`${fb.toFixed(1)} DB`, W - pad, 38);
    ctx.textAlign = "left";
    ctx.fillStyle = DRY;
    ctx.fillText("HIT", pad, 4);
  },
};

// adt — the two taps against the dry signal: where each sits in time, and how loud it plays.

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

export default {
  taps_screen(lcd) {
    const { ctx, width: W, height: H, params, output, state } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);

    const pad = 10;
    const base = H - 14;
    const top = 12;
    const span = Math.max(1, W - pad * 2);
    const tall = Math.max(1, base - top);

    // The blend is the engine's @mix, on the equal-power curve it applies: all wet when unset.
    const mix = clamp01(params["@mix"] ?? 1);
    const wet = Math.sin((mix * Math.PI) / 2);
    const dry = Math.cos((mix * Math.PI) / 2);

    // The time axis, with a faint tick every tenth.
    ctx.strokeStyle = "#6b6b6b";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(pad, base + 0.5);
    ctx.lineTo(W - pad, base + 0.5);
    for (let i = 1; i < 10; i++) {
      const x = Math.round(pad + (span * i) / 10) + 0.5;
      ctx.moveTo(x, base);
      ctx.lineTo(x, base + 3);
    }
    ctx.stroke();

    // The dry signal: a white bar at time zero.
    const bar = (x, level, color, name) => {
      const h = Math.max(1, tall * clamp01(level));
      ctx.fillStyle = color;
      ctx.fillRect(Math.round(x) - 3, base - h, 6, h);
      ctx.fillStyle = color;
      ctx.font = "8px ui-monospace, monospace";
      ctx.textAlign = "center";
      ctx.fillText(name, Math.round(x), base + 11);
    };
    bar(pad + 3, dry, "#ffffff", "DRY");

    // Each tap at its delay, as loud as its level times the wet side of the blend.
    const aTime = clamp01(params["A Delay"] ?? 0.3);
    const bTime = clamp01(params["B Delay"] ?? 0.6);
    const aLevel = clamp01(params["A Level"] ?? 0.7) * wet;
    const bLevel = clamp01(params["B Level"] ?? 0.7) * wet;
    bar(pad + 3 + (span - 6) * aTime, aLevel, "#3d7dff", "A");
    bar(pad + 3 + (span - 6) * bTime, bLevel, "#3ec96b", "B");

    // The output, smoothed: a thin orange line across the top that swells with what leaves.
    const out = output.length ? clamp01(output[output.length - 1]) : 0;
    state.out = (state.out ?? 0) * 0.7 + out * 0.3;
    if (state.out > 0.01) {
      ctx.fillStyle = "#ff6a1a";
      ctx.fillRect(pad, 4, span * state.out, 2);
    }

    ctx.fillStyle = "#6b6b6b";
    ctx.font = "8px ui-monospace, monospace";
    ctx.textAlign = "right";
    ctx.fillText("TAPS", W - pad, 10);
  },
};

// echo — the repeats the delay makes: where each one lands in time, and how loud it plays.

const DRY = "#ffffff";
const WET = "#3d7dff";
const GRID = "#6b6b6b";
const FONT = "8px ui-monospace, monospace";
// The window drawn, in ms: two seconds holds a dub delay's tail at any Time the knob allows.
const WINDOW_MS = 2000;

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

export default {
  repeats(lcd) {
    const { ctx, width: W, height: H, params, output, state, now } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;

    const pad = 8;
    const base = H - 12;
    const top = 14;
    const span = Math.max(1, W - pad * 2);
    const tall = Math.max(1, base - top);

    const time = Math.max(1, params["Time"] ?? 250);
    const feedback = clamp01(params["Feedback"] ?? 0.6);
    // The engine's blend around the delay: the dry hit shrinks as the repeats grow.
    const mix = clamp01(params["@mix"] ?? 1);
    const wet = Math.sin((mix * Math.PI) / 2);
    const dry = Math.cos((mix * Math.PI) / 2);

    // The time axis, a tick every 250 ms.
    ctx.strokeStyle = GRID;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(pad, base + 0.5);
    ctx.lineTo(W - pad, base + 0.5);
    for (let ms = 250; ms < WINDOW_MS; ms += 250) {
      const x = Math.round(pad + (span * ms) / WINDOW_MS) + 0.5;
      ctx.moveTo(x, base);
      ctx.lineTo(x, base + 3);
    }
    ctx.stroke();

    const bar = (ms, level, color) => {
      const x = Math.round(pad + (span * ms) / WINDOW_MS);
      const h = Math.max(1, tall * clamp01(level));
      ctx.fillStyle = color;
      ctx.fillRect(x - 1, base - h, 3, h);
    };

    // The dry hit at zero, then each repeat one Time later, a Feedback quieter than the last.
    bar(0, dry, DRY);
    let level = wet;
    for (let n = 1; n <= 64; n++) {
      const ms = n * time;
      if (ms >= WINDOW_MS || level < 0.01) break;
      bar(ms, level, WET);
      level *= feedback;
    }

    // A dot riding the repeats while audio leaves the module, so a running delay reads as one.
    const out = Array.isArray(output) && output.length ? clamp01(output[output.length - 1] ?? 0) : 0;
    state.out = (state.out ?? 0) * 0.7 + out * 0.3;
    if (state.out > 0.02) {
      const phase = (now % WINDOW_MS) / WINDOW_MS;
      ctx.fillStyle = WET;
      ctx.beginPath();
      ctx.arc(pad + span * phase, top - 6, 2, 0, Math.PI * 2);
      ctx.fill();
    }

    // The one value that matters, big; the rest small.
    ctx.fillStyle = DRY;
    ctx.textAlign = "right";
    ctx.font = "bold 11px ui-monospace, monospace";
    ctx.fillText(`${Math.round(time)} MS`, W - pad, 11);
    ctx.font = FONT;
    ctx.fillStyle = GRID;
    ctx.textAlign = "left";
    ctx.fillText(`FB ${Math.round(feedback * 100)}%`, pad, 10);
  },
};

// hombre — the level going IN against the level coming OUT, so what the texture adds or takes is seen.

const IN = "#3d7dff";
const OUT = "#ff6a1a";
const GRID = "#6b6b6b";
const FONT = "8px ui-monospace, monospace";

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

/** One envelope, mirrored about `mid`, oldest on the left and NOW at the right edge. */
function envelope(ctx, data, len, x0, w, mid, half, color, fill) {
  if (!data.length || len < 2) return;
  const step = w / (len - 1);
  const offset = len - data.length;
  ctx.beginPath();
  for (let i = 0; i < data.length; i++) {
    const x = x0 + (offset + i) * step;
    const y = mid - clamp01(data[i] ?? 0) * half;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  for (let i = data.length - 1; i >= 0; i--)
    ctx.lineTo(x0 + (offset + i) * step, mid + clamp01(data[i] ?? 0) * half);
  ctx.closePath();
  if (fill) {
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.35;
    ctx.fill();
    ctx.globalAlpha = 1;
  }
  ctx.strokeStyle = color;
  ctx.lineWidth = 1;
  ctx.stroke();
}

export default {
  levels(lcd) {
    const { ctx, width: W, height: H, params, input, output } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;

    const x0 = 6;
    const w = Math.max(1, W - 12);
    const top = 14;
    const bottom = H - 6;
    const mid = (top + bottom) / 2;
    const half = Math.max(1, (bottom - top) / 2);

    ctx.strokeStyle = GRID;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x0, Math.round(mid) + 0.5);
    ctx.lineTo(x0 + w, Math.round(mid) + 0.5);
    ctx.stroke();

    const inp = Array.isArray(input) ? input : [];
    const out = Array.isArray(output) ? output : [];
    const len = Math.max(inp.length, out.length);
    if (len > 1) {
      // What goes in underneath, filled; what comes out on top, as a line.
      envelope(ctx, inp, len, x0, w, mid, half, IN, true);
      envelope(ctx, out, len, x0, w, mid, half, OUT, false);
    } else {
      // No audio yet: the two settings as bars, so the screen still says where the texture sits.
      const voicing = clamp01(params["Voicing"] ?? 0.5);
      const intensity = clamp01(params["Intensity"] ?? 0.5);
      const barW = Math.max(1, w / 2 - 6);
      ctx.fillStyle = IN;
      ctx.fillRect(x0, bottom - (bottom - top) * voicing, barW, (bottom - top) * voicing);
      ctx.fillStyle = OUT;
      ctx.fillRect(x0 + w / 2 + 6, bottom - (bottom - top) * intensity, barW, (bottom - top) * intensity);
    }

    ctx.fillStyle = IN;
    ctx.textAlign = "left";
    ctx.fillText("IN", x0, 10);
    ctx.fillStyle = OUT;
    ctx.fillText("OUT", x0 + 18, 10);
  },
};

// purest-echo — one screen: the dry hit and the four taps, spaced evenly across Time, each as tall as its level.

const TIME = "#ff6a1a";
const TAP = "#3d7dff";
const GRID = "#6b6b6b";
const INK = "#ffffff";
const FONT = "8px ui-monospace, monospace";

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

export default {
  taps_screen(lcd) {
    const { ctx, width: W, height: H, params } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;

    const pad = 6;
    const top = 13;
    const h = Math.max(1, H - top - pad - 1);
    const w = Math.max(1, W - pad * 2);
    const base = top + h;
    const time = clamp01(params["Time"] ?? 0.5);
    const span = 0.08 + time * 0.92;

    ctx.strokeStyle = GRID;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(pad, base + 0.5);
    ctx.lineTo(pad + w, base + 0.5);
    ctx.stroke();

    // The dry hit at zero, full height, for the taps to be read against.
    ctx.fillStyle = INK;
    ctx.fillRect(pad, top, 2, h);

    ctx.strokeStyle = TIME;
    ctx.beginPath();
    const tx = Math.round(pad + span * (w - 2)) + 0.5;
    ctx.moveTo(tx, base + 3);
    ctx.lineTo(tx, top - 2);
    ctx.stroke();

    ctx.fillStyle = TAP;
    for (let k = 1; k <= 4; k++) {
      const lvl = clamp01(params[`Tap ${k}`] ?? (k === 1 ? 1 : 0));
      const x = pad + (k / 4) * span * (w - 2);
      const bh = Math.max(1, lvl * h);
      ctx.fillRect(Math.round(x) - 1, base - bh, 3, bh);
      ctx.beginPath();
      ctx.arc(Math.round(x) + 0.5, base - bh, 2, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.textAlign = "left";
    ctx.fillStyle = TIME;
    ctx.fillText(`TIME ${Math.round(time * 100)}`, pad, 9);
    ctx.textAlign = "right";
    ctx.fillStyle = TAP;
    ctx.fillText("TAPS", W - pad, 9);
  },
};

// The echoes: the dry hit, then repeats spaced by Delay and shrinking by Feedbak (time is relative, not ms).
const FONT = "8px ui-monospace, monospace";

function clamp(v, lo, hi) {
  return Math.min(hi, Math.max(lo, Number.isFinite(v) ? v : lo));
}

export default {
  taps_screen(lcd) {
    const { ctx, width: W, height: H, params } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    const time = clamp(params["Delay"] ?? 0.5, 0, 1);
    const fb = clamp(params["Feedbak"] ?? 0.5, 0, 0.98);
    const base = H - 4;
    const top = 12;
    const span = Math.max(1, base - top);
    const x0 = 6;
    const step = Math.max(4, (0.08 + 0.42 * time) * Math.max(1, W - x0 - 4));
    ctx.strokeStyle = "#6b6b6b";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, base + 0.5);
    ctx.lineTo(W, base + 0.5);
    ctx.stroke();
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(x0, top, 2, span);
    let amp = 1;
    for (let i = 1; i < 64; i++) {
      amp *= fb;
      const x = x0 + i * step;
      if (x > W - 2 || amp < 0.02) break;
      const h = span * amp;
      ctx.fillStyle = "#3d7dff";
      ctx.fillRect(x, base - h, 2, h);
    }
    ctx.font = FONT;
    ctx.fillStyle = "#3d7dff";
    ctx.fillText("TIME " + Math.round(time * 100), 2, 8);
    ctx.fillText("FDBK " + Math.round(fb * 100), Math.max(2, W - 48), 8);
  },
};

// delay — the repeats one hit leaves: each tap Feedback dB under the last, until they fall below -60 dB.
// The delay TIME is the plugin's own setting and no param, so the taps are evenly spaced.

